var T = function (s) { return window.FTC_i18n ? window.FTC_i18n.t(s) : s; };
/* Ekip sayıları ekip.json'dan güncellenir; metinlerde {n} kişi, {k} kurul yerine geçer */
var COUNTS = { n: 38, k: 6 };
var fmt = function (s) { return T(s).replace('{n}', COUNTS.n).replace('{k}', COUNTS.k); };
function renderTeamTitle() { var el = document.getElementById('team-title'); if (el) el.textContent = fmt('{k} kurul, {n} kişi, tek ekip'); }
