function renderEvents() {
    $('ev-track').innerHTML = EVENTS.map(function (e, i) {
        return '<button class="ev" type="button" data-idx="' + i + '"><img src="' + e.cover + '" alt="" loading="lazy" data-fx><span class="ev-txt"><time>' + esc(T(e.date)) + '</time><h4>' + esc(T(e.title)) + '</h4><span class="ev-open">' + esc(T('Detayları gör')) + '</span></span></button>';
    }).join('');
    var tl = $('timeline'), seen = {};
    tl.querySelectorAll('.tl-dot, .tl-month').forEach(function (n) { n.remove(); });
    EVENTS.forEach(function (e, i) {
        var x = (i / (EVENTS.length - 1)) * 100;
        tl.insertAdjacentHTML('beforeend', '<span class="tl-dot" style="left:' + x + '%"></span>');
        if (!seen[e.month]) { seen[e.month] = 1; tl.insertAdjacentHTML('beforeend', '<button class="tl-month" type="button" data-idx="' + i + '" style="left:' + x + '%">' + esc(innerWidth <= 960 ? T(e.month).slice(0, 3) : T(e.month)) + '</button>'); }
    });
}
$('ev-track').addEventListener('click', function (e) { var b = e.target.closest('.ev'); if (b) openEvent(+b.dataset.idx, b); });
$('timeline').addEventListener('click', function (e) { var b = e.target.closest('.tl-month'); if (b) scrollToEvent(+b.dataset.idx); });

var modal = $('ev-modal'), modalIdx = 0, imgIdx = 0, lastFocus = null;
function openEvent(i, from) {
    modalIdx = i; imgIdx = 0; lastFocus = from || document.activeElement;
    renderModal(); modal.classList.add('open'); if (lenis) lenis.stop(); else root.style.overflow = 'hidden';
    modal.querySelector('.x').focus();
}
function closeEvent() { modal.classList.remove('open'); if (lenis) lenis.start(); else root.style.overflow = ''; if (lastFocus) lastFocus.focus(); }
function renderModal() {
    var e = EVENTS[modalIdx], imgs = e.imgs.length ? e.imgs : [e.cover];
    imgIdx = (imgIdx + imgs.length) % imgs.length;
    var prev = EVENTS[(modalIdx - 1 + EVENTS.length) % EVENTS.length], next = EVENTS[(modalIdx + 1) % EVENTS.length];
    modal.innerHTML =
        '<div class="bd" data-close></div><div class="win">' +
        '<button class="x" type="button" data-close aria-label="' + esc(T('Kapat')) + '">×</button>' +
        '<div class="stage"><img src="' + imgs[imgIdx] + '" alt="" data-fx>' +
        (imgs.length > 1 ? '<button class="nav-btn prev" type="button" data-img="-1" aria-label="‹">‹</button><button class="nav-btn next" type="button" data-img="1" aria-label="›">›</button>' : '') + '</div>' +
        (imgs.length > 1 ? '<div class="thumbs">' + imgs.map(function (s, k) { return '<button type="button" data-goto="' + k + '" aria-current="' + (k === imgIdx) + '"><img src="' + s + '" alt="" loading="lazy"></button>'; }).join('') + '</div>' : '') +
        '<div class="body"><time>' + esc(T(e.mdate)) + '</time><h3 id="ev-modal-title">' + esc(T(e.title)) + '</h3>' +
        e.paras.map(function (p) { return '<p>' + T(p) + '</p>'; }).join('') + '</div>' +
        '<div class="foot"><button type="button" data-ev="-1">← ' + esc(T(prev.title)) + '</button>' +
        '<button type="button" data-ev="1">' + esc(T(next.title)) + ' →</button></div></div>';
    fx(modal);
}
modal.addEventListener('click', function (e) {
    var t = e.target;
    if (t.closest('[data-close]')) return closeEvent();
    var b = t.closest('[data-img]'); if (b) { imgIdx += +b.dataset.img; renderModal(); return; }
    b = t.closest('[data-goto]'); if (b) { imgIdx = +b.dataset.goto; renderModal(); return; }
    b = t.closest('[data-ev]'); if (b) { modalIdx = (modalIdx + +b.dataset.ev + EVENTS.length) % EVENTS.length; imgIdx = 0; renderModal(); }
});
document.addEventListener('keydown', function (e) {
    if (!modal.classList.contains('open')) return;
    if (e.key === 'Escape') closeEvent();
    if (e.key === 'ArrowRight') { imgIdx++; renderModal(); }
    if (e.key === 'ArrowLeft') { imgIdx--; renderModal(); }
});
window.FTC_openEvent = function (id) { var i = EVENTS.map(function (e) { return e.id; }).indexOf(id); if (i >= 0) openEvent(i); };

