/* Omurga boyunca uçuş: mesafeye göre süre, ağ çizgi çizer, ışık parlar */
function fly(y) {
    var dist = Math.abs(y - scrollY), dur = clamp(.9 + dist / 4200, 1.1, 2.8);
    if (reduce) { scrollTo(0, y); return; }
    root.classList.add('flying');
    var done = function () { root.classList.remove('flying'); };
    var easeIO = function (t) { return t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; };
    if (lenis) lenis.scrollTo(y, { duration: dur, easing: easeIO, lock: true, force: true, onComplete: done });
    else {
        var y0 = scrollY, t0 = performance.now();
        requestAnimationFrame(function stepF(t) { var k = Math.min(1, (t - t0) / (dur * 1000)); scrollTo(0, y0 + (y - y0) * easeIO(k)); if (k < 1) requestAnimationFrame(stepF); else done(); });
    }
}
