/* ---------------------------------------------------------------
   6) TEPKİLİ AĞ (arka plan canvas) — omurga ucuna çekilir, patlamada dalgalanır
   --------------------------------------------------------------- */
var NET = (function () {
    var cv = $('net-canvas'), cx = cv.getContext('2d'), dpr = Math.min(devicePixelRatio || 1, 1.5);
    var W, H, P = [], waves = [], attr = null, lastY = scrollY, running = true;
    function size() {
        W = innerWidth; H = innerHeight; cv.width = W * dpr; cv.height = H * dpr; cx.setTransform(dpr, 0, 0, dpr, 0, 0);
        var n = W < 700 ? 42 : W < 1200 ? 64 : 84;
        while (P.length < n) P.push({ x: Math.random() * W, y: Math.random() * H, vx: (Math.random() - .5) * .3, vy: (Math.random() - .5) * .3, r: Math.random() * 2 + .8, a: Math.random() * .4 + .3 });
        P.length = n;
    }
    function frame(t) {
        if (!running) return;
        var dy = (scrollY - lastY) * 0.18; lastY = scrollY;
        cx.clearRect(0, 0, W, H);
        // patlama dalgaları
        for (var w = waves.length - 1; w >= 0; w--) {
            var wv = waves[w], age = (t - wv.t0) / 1000;
            if (age > 1.2) { waves.splice(w, 1); continue; }
            wv.rad = Math.max(0, age * 520);
            cx.beginPath(); cx.arc(wv.x, wv.y, wv.rad, 0, Math.PI * 2);
            cx.strokeStyle = 'rgba(0,210,255,' + (0.45 * (1 - age / 1.2)) + ')'; cx.lineWidth = 2; cx.stroke();
        }
        for (var i = 0; i < P.length; i++) {
            var p = P[i];
            p.y -= dy;
            if (attr) {
                var ax = attr.x - p.x, ay = attr.y - p.y, d = Math.sqrt(ax * ax + ay * ay);
                if (d < 280 && d > 1) { var f = (1 - d / 280) * 0.045; p.vx += ax / d * f; p.vy += ay / d * f; }
            }
            for (var k = 0; k < waves.length; k++) {
                var q = waves[k], qx = p.x - q.x, qy = p.y - q.y, qd = Math.sqrt(qx * qx + qy * qy);
                if (Math.abs(qd - q.rad) < 40 && qd > 1) { p.vx += qx / qd * .9; p.vy += qy / qd * .9; }
            }
            p.vx *= 0.96; p.vy *= 0.96;
            p.vx += (Math.random() - .5) * .03; p.vy += (Math.random() - .5) * .03;
            p.x += p.vx; p.y += p.vy;
            if (p.x < -20) p.x = W + 20; if (p.x > W + 20) p.x = -20;
            if (p.y < -20) p.y = H + 20; if (p.y > H + 20) p.y = -20;
        }
        cx.lineWidth = 1;
        for (i = 0; i < P.length; i++) {
            var a = P[i], hotA = attr ? Math.max(0, 1 - Math.hypot(attr.x - a.x, attr.y - a.y) / 300) : 0;
            for (var j = i + 1; j < P.length; j++) {
                var b = P[j], ddx = a.x - b.x, ddy = a.y - b.y, dd = ddx * ddx + ddy * ddy;
                if (dd < 22500) {
                    var hot = attr ? Math.max(hotA, Math.max(0, 1 - Math.hypot(attr.x - b.x, attr.y - b.y) / 300)) : 0;
                    cx.strokeStyle = 'rgba(0,210,255,' + ((1 - dd / 22500) * (0.18 + hot * 0.6)) + ')';
                    cx.beginPath(); cx.moveTo(a.x, a.y); cx.lineTo(b.x, b.y); cx.stroke();
                }
            }
            if (attr && hotA > 0.25) {
                cx.strokeStyle = 'rgba(255,255,255,' + (hotA * 0.35) + ')';
                cx.beginPath(); cx.moveTo(a.x, a.y); cx.lineTo(attr.x, attr.y); cx.stroke();
            }
            cx.beginPath(); cx.arc(a.x, a.y, a.r + hotA * 1.8, 0, Math.PI * 2);
            cx.fillStyle = 'rgba(' + (hotA > .3 ? '255,255,255' : '0,210,255') + ',' + Math.min(1, a.a + hotA * .6) + ')'; cx.fill();
            if (Math.abs(dy) > 2.5) { cx.strokeStyle = 'rgba(0,210,255,' + Math.min(.55, Math.abs(dy) / 30) + ')'; cx.beginPath(); cx.moveTo(a.x, a.y); cx.lineTo(a.x, a.y + dy * 5); cx.stroke(); }
        }
        requestAnimationFrame(frame);
    }
    size(); addEventListener('resize', size);
    document.addEventListener('visibilitychange', function () { running = !document.hidden; if (running) { lastY = scrollY; requestAnimationFrame(frame); } });
    if (reduce) { running = false; requestAnimationFrame(function (t) { running = true; frame(t); running = false; }); }
    else requestAnimationFrame(frame);
    return {
        attract: function (pt) { attr = pt; },
        wave: function (x, y) { if (!reduce) waves.push({ x: x, y: y, t0: performance.now(), rad: 0 }); }
    };
})();

