            s2.el.style.transform = 'translate(' + (s2.dx * (1 - e)).toFixed(1) + 'px,' + (s2.dy * (1 - e)).toFixed(1) + 'px) scale(' + (.35 + .65 * e).toFixed(3) + ')';
