            if (e >= 1) { t.style.transform = ''; t.style.opacity = ''; return; }
            var r1 = Math.sin(i * 91.7) * 1e4; r1 -= Math.floor(r1); var ang = r1 * Math.PI * 2, D = 300 + (i % 3) * 60;
