var toWebp = function (p) { return WEBP[p] || p; };
fetch('ekip.json', { cache: 'no-cache' }).then(function (r) { return r.ok ? r.json() : null; }).then(function (d) {
    if (!d || typeof d !== 'object') return;
    var shortOf = {}; TEAM.forEach(function (k) { shortOf[k.key] = k.short; });
    var next = Object.keys(d).filter(function (k) { return Array.isArray(d[k]) && d[k].length; }).map(function (k) {
        return { key: k, short: shortOf[k] || k, members: d[k].map(function (m) {
            return { n: m.name, r: m.role, li: m.linkedin || null, em: m.email || null, img: m.image && m.image !== 'avatar-placeholder' ? toWebp(m.image) : null };
        }) };
    });
    if (!next.length) return;
    TEAM.length = 0; next.forEach(function (x) { TEAM.push(x); });
    if (!TEAM.some(function (k) { return k.key === teamKey; })) teamKey = TEAM[0].key;
    var uniq = {}; TEAM.forEach(function (k) { k.members.forEach(function (m) { uniq[m.n] = 1; }); });
    COUNTS.n = Object.keys(uniq).length; COUNTS.k = TEAM.length;
    var sts = document.querySelectorAll('#p-hakkimizda .stat strong');
    if (sts[0]) sts[0].dataset.count = COUNTS.n;
    if (sts[3]) sts[3].dataset.count = COUNTS.k;
    renderTeamTitle(); renderTabs(); renderTeam(); renderHub(); onScroll();
}).catch(function () {});

var ANN = null;
function renderAnn() {
    if (!ANN) return;
    var lang = window.FTC_i18n ? window.FTC_i18n.getLang() : 'tr';
    document.querySelector('.ann-list').innerHTML = ANN.map(function (a, i) {
        var dt = new Date((a.date || '') + 'T00:00:00');
        var ds = isNaN(dt) ? (a.date || '') : dt.toLocaleDateString(lang === 'en' ? 'en-US' : 'tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
        return '<a class="ann" style="--i:' + i + '" href="duyurular.html">' + (i === 0 ? '<span class="new-badge">' + esc(T('YENİ')) + '</span>' : '') +
            (a.image ? '<img src="' + esc(toWebp(a.image)) + '" alt="" loading="lazy" data-fx>' : '<span></span>') +
            '<div><time>' + esc(ds) + ' · ' + esc(T(a.category || 'Genel')) + '</time><h4>' + esc(T((a.title || '').trim())) + '</h4></div></a>';
    }).join('');
    fx(document.querySelector('.ann-list')); onScroll();
}
fetch('site-data.json', { cache: 'no-cache' }).then(function (r) { return r.ok ? r.json() : null; }).then(function (d) {
    if (!d || !Array.isArray(d.announcements) || !d.announcements.length) return;
    ANN = d.announcements.slice().sort(function (a, b) { return (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0) || String(b.date || '').localeCompare(String(a.date || '')); }).slice(0, 3);
    renderAnn();
}).catch(function () {});
document.addEventListener('ftc:langchange', renderAnn);

