/* =====================================================================
   BİZE SORU SOR — sunucu API'si (GitHub'a güvenli kayıt) + Formspree e-postası.
   Not: Eski sayfadaki, tarayıcıda açıkta duran GitHub token'ıyla yapılan
   ikinci kayıt kaldırıldı; /api/submit-question aynı işi sunucuda yapıyor.
   ===================================================================== */
(function () {
    var form = document.getElementById('ask-question-form'), status = document.getElementById('submit-status'), btn = document.getElementById('submit-question-btn');
    if (!form) return;
    var t = function (s) { return window.FTC_i18n ? window.FTC_i18n.t(s) : s; };
    function showToast(msg, isError) {
        var old = document.querySelector('.toast-notification'); if (old) old.remove();
        var el = document.createElement('div'); el.className = 'toast-notification' + (isError ? ' error' : '');
        el.innerHTML = '<span class="toast-icon">' + (isError ? '!' : '✓') + '</span> <span></span>'; el.lastChild.textContent = msg;
        document.body.appendChild(el);
        setTimeout(function () { el.classList.add('show'); }, 50);
        setTimeout(function () { el.classList.remove('show'); setTimeout(function () { el.remove(); }, 400); }, 4000);
    }
    form.addEventListener('submit', async function (e) {
        e.preventDefault();
        status.style.display = 'block'; status.style.color = '#cbd5e1'; status.textContent = t('Gönderiliyor...'); btn.disabled = true;
        var name = document.getElementById('q-name').value.trim(), email = document.getElementById('q-email').value.trim(), body = document.getElementById('q-message').value.trim();
        var apiOk = false, mailOk = false;
        try {
            var res = await Promise.all([
                fetch('/api/submit-question', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: name, email: email, message: body }) }).catch(function () { return null; }),
                fetch('https://formspree.io/f/xgogbewa', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, body: JSON.stringify({ name: name, email: email, message: body, _subject: 'FinTeClub - Yeni Soru' }) }).catch(function () { return null; })
            ]);
            apiOk = !!(res[0] && res[0].ok); mailOk = !!(res[1] && res[1].ok);
        } catch (err) { console.warn('Gönderim hatası:', err); }
        btn.disabled = false; status.style.display = 'none';
        if (apiOk || mailOk) { showToast(t('Sorunuz başarıyla gönderildi! Teşekkür ederiz.'), false); form.reset(); }
        else showToast(t('Bir sorun oluştu, lütfen daha sonra tekrar deneyin.'), true);
    });
})();
